package main

import (
	"bufio"
	"fmt"
	"os"
)

var (
	s   string
	qq  = "QAQ"
	arr [][]int
)

func q(m, n int) int {
	if arr[n][m] != -1 {
		return arr[n][m]
	}
	if m == 0 {
		return 1
	}
	if n == 0 {
		return 0
	}

	i := 0
	if qq[m-1] == s[n-1] {
		i = q(m-1, n-1)
	}

	j := q(m, n-1)
	arr[n][m] = i + j
	return i + j
}

func main() {
	in := bufio.NewReader(os.Stdin)
	fmt.Fscan(in, &s)

	arr = make([][]int, len(s)+1)
	for i := range arr {
		arr[i] = make([]int, 4)
		for j := range arr[i] {
			arr[i][j] = -1
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	fmt.Fprintln(out, q(3, len(s)))
}

